Linux 명령어 실습
• Cat 프로그램과 stdin, stdout, stderr
/* main() 함수 호출 전에 3개 파일 open 
stdin = open(“/dev/tty”, O_RDONLY);
stdout = open(“/dev/tty”, O_WRONLY | O_CREAT | O_TRUNC);
stderr = open(“/dev/tty”, O_WRONLY | O_CREAT | O_TRUNC);
*/
main() {
char  buf[BUF_SIZE];
int n;
n = read(stdin, buf, BUF_SIZE);
while (n > 0) {
write(stdout, buf, n);
n = read(stdin, buf, BUF_SIZE);
}
}

